// Somebody else's words, on the page, at THREE WEIGHTS — and every one of them reads its
// numbers from `quote-card`, the same module that draws the social preview, so there is
// nothing to keep in sync by hand and nothing that can drift when either is touched.
//
//   card     the poster: the portrait bleeding out of the right edge, the ghost mark, the
//            words composed in the band. It IS the link preview, drawn in the DOM.
//   feature  the page's own weight: no frame, no portrait — the mark, the words set at
//            display size over it, one line of attribution. What a quote's own page opens
//            with, and the step the other two left missing.
//   prose    a quotation inside an article, at the page's own type, marked by a small
//            mark rather than a rule. What an embed in a feed card is.
//
// WHAT THE THREE CANNOT SHARE WITH THE STILL is measurement. A browser knows exactly how
// wide a character is and the still has no way to find out, so the still estimates `ch`
// and these state the measure in real `ch` and let the layout engine be right. They agree
// on how many characters a line carries; they may disagree about which word ends one.
//
// It renders a real `<blockquote>` with a real `<cite>`, because that is what this is,
// and a screen reader announcing "blockquote" is information the styling cannot carry.

import {
  assert,
  BLOCK_AT,
  CAP,
  CARD_H,
  CARD_W,
  DATE_EM,
  DESC,
  DISSOLVE,
  EDGE,
  FACE_FEATHER,
  FACE_SHARE,
  FOCUS,
  GLOW,
  GROUND,
  glowOf,
  INDENT,
  LINE,
  MARGIN,
  MARK_BLUR,
  MARK_BOX,
  MARK_EM,
  MARK_OPACITY,
  MARK_PATH,
  NAME_EM,
  type Quote as QuoteData,
  type QuoteTone,
  quoteClean,
  quoteMeasure,
  quoteSet,
} from "@/registry/base-nova/lib/quote-card"
import "./quote.css"

export type QuoteVariant = "card" | "feature" | "prose"

export interface QuoteProps extends QuoteData {
  /** Which weight. Defaults to `prose`, the one that shouts least. */
  variant?: QuoteVariant
  /** The picture's own colour, ground and ink. Derived from the pixels by whoever has
   *  them (`toneFrom`); without it the card is neutral, which is honest — a hue from a
   *  hash of the author's name is a colour nobody chose, and it lands wherever the hash
   *  lands. */
  tone?: QuoteTone
  /** Where the subject sits across the portrait, 0 to 1, so the card's dissolve does
   *  not eat it. Same number the still takes, from the same detector. */
  focus?: number
  /** The width the measure is set against, in px. For `card` and `feature`, and only
   *  worth passing when the quote is not in the usual reading column.
   *
   *  `source` is drawn in `feature` and `prose`, never on the card: the still has
   *  nowhere to put a link, and the card matching its own preview outranks carrying one
   *  more affordance. */
  width?: number
  className?: string
  children?: React.ReactNode
}

/** The reading column a quote is set for, matching the site's `max-w-3xl`. */
export const QUOTE_WIDTH = 768

const pct = (n: number) => `${(n * 100).toFixed(3)}%`
/** A hundredth of the CONTAINER's width, whatever property it lands on. `%` means that
 *  only for horizontal offsets and widths; everywhere else it means something surprising
 *  — as font-size it is the parent's font-size, as an abspos height the container's
 *  height. */
const cqw = (n: number) => `${(n * 100).toFixed(3)}cqw`

const unit = 1 / 150
const aspect = CARD_W / CARD_H

export function Quote({
  text,
  author,
  source,
  date,
  variant = "prose",
  tone,
  focus = FOCUS,
  width = QUOTE_WIDTH,
  className,
  children,
}: QuoteProps) {
  const words = quoteClean(text)
  const body = children ?? <p>{words}</p>
  const ink = tone?.accent ?? "currentColor"
  const classes = `ag-quote ag-quote-${variant}${className ? ` ${className}` : ""}`

  if (variant === "prose")
    return (
      <figure
        className={classes}
        style={{ "--ag-quote-ink": ink } as React.CSSProperties}
      >
        <Mark />
        <blockquote className="ag-quote-body">{body}</blockquote>
        <By author={author} date={date} source={source} face />
      </figure>
    )

  if (variant === "feature") {
    // The words are set in from the left by the still's INDENT and the mark sits at the
    // margin the words are indented FROM, so the two stack the way they do on the card —
    // the overlap is the depth. No band to centre in: the block flows, and it starts
    // half way down the mark so the words climb into it rather than hang below it.
    const column = 1 - unit * INDENT
    const { size } = quoteSet(words, width * column)
    return (
      <figure
        className={classes}
        style={
          {
            "--ag-quote-ink": ink,
            "--ag-quote-indent": pct(unit * INDENT),
            "--ag-quote-measure": `${quoteMeasure(words.length)}ch`,
            "--ag-quote-size": cqw(size / width),
            "--ag-quote-mark": cqw(MARK_EM / aspect),
            "--ag-quote-mark-fill": String(MARK_OPACITY),
            "--ag-quote-soften": cqw((MARK_EM / aspect) * MARK_BLUR),
            "--ag-quote-line": String(LINE),
            "--ag-quote-gap": cqw(unit * EDGE),
          } as React.CSSProperties
        }
      >
        <Mark />
        <blockquote className="ag-quote-body">{body}</blockquote>
        <By author={author} date={date} source={source} face />
      </figure>
    )
  }

  // THE CARD. Every number below is the still's, recomputed as a share of the frame
  // rather than in pixels, so one set of constants drives both surfaces at any size.
  //
  // BLOCK_AT is the one that cannot cross: placing a block at an arbitrary fraction of
  // the slack means knowing how tall it turned out, and here the browser decides that
  // after this code has run. Centring is the only fraction the DOM gives for free, so
  // the two surfaces agree exactly while BLOCK_AT is a half and would need a measuring
  // pass the day it is not.
  assert(
    BLOCK_AT === 0.5,
    `the web card can only centre its words; BLOCK_AT is ${BLOCK_AT}`,
  )
  const height = width / aspect
  // Without a picture the words take the whole frame, exactly as the still gives it to
  // them; sizing them for the picture's column anyway set a bare quote 59% small.
  const column = author?.avatar
    ? 1 - FACE_SHARE - unit * (MARGIN + INDENT)
    : 1 - unit * (2 * MARGIN + INDENT)
  // The band the still composes in, so a quote too long for the frame THROWS here the
  // way it throws there. Without it the fixed aspect-ratio box just clipped the words
  // mid-sentence, silently — the one thing the module promises never happens.
  const nameSize = NAME_EM * width
  const band = height - 2 * unit * EDGE * width - (CAP + DESC) * nameSize
  const { size } = quoteSet(words, width * column, band)

  // The picture is a square as tall as the frame, slid so the subject clears the
  // dissolve, and bounded so it neither leaves ground at the right edge nor empties the
  // fade. Identical arithmetic to the still's, in fractions of the width.
  const faceX = 1 - FACE_SHARE
  const featherX = faceX + (1 - faceX) * FACE_FEATHER
  const slotX = Math.max(
    1 - 1 / aspect,
    Math.min(faceX, (featherX + 1) / 2 - focus / aspect),
  )
  // The mask runs across the PICTURE, so the stops are in its own coordinates.
  const into = (x: number) => pct((x - slotX) * aspect)
  const dissolve = `linear-gradient(to right, ${DISSOLVE.map(
    ([at, on]) => `rgb(0 0 0 / ${on}) ${into(faceX + (featherX - faceX) * at)}`,
  ).join(", ")})`

  return (
    <figure
      className={classes}
      style={
        {
          "--ag-quote-ground": `radial-gradient(${GLOW.r * 100}% ${GLOW.r * 100}% at ${GLOW.cx * 100}% ${GLOW.cy * 100}%, ${glowOf(tone?.ground ?? GROUND).join(", ")})`,
          "--ag-quote-ink": ink,
          "--ag-quote-aspect": `${CARD_W} / ${CARD_H}`,
          "--ag-quote-margin": pct(unit * MARGIN),
          "--ag-quote-indent": pct(unit * (MARGIN + INDENT)),
          "--ag-quote-edge": pct(unit * EDGE * aspect),
          "--ag-quote-floor": pct(
            unit * EDGE * aspect + (CAP + DESC) * NAME_EM * aspect,
          ),
          "--ag-quote-column": pct(column),
          "--ag-quote-measure": `${quoteMeasure(words.length)}ch`,
          "--ag-quote-size": cqw(size / width),
          "--ag-quote-name": cqw(NAME_EM),
          "--ag-quote-date": cqw(DATE_EM),
          "--ag-quote-mark": cqw(MARK_EM / aspect),
          "--ag-quote-mark-fill": String(MARK_OPACITY),
          "--ag-quote-soften": cqw((MARK_EM / aspect) * MARK_BLUR),
          "--ag-quote-line": String(LINE),
          "--ag-quote-slot": pct(slotX),
          "--ag-quote-square": cqw(1 / aspect),
          "--ag-quote-dissolve": dissolve,
        } as React.CSSProperties
      }
    >
      {author?.avatar && (
        // Decorative: the name below it is the accessible attribution, and a screen
        // reader reading the same person twice is noise.
        // biome-ignore lint/performance/noImgElement: an item cannot assume next/image
        <img className="ag-quote-bleed" src={author.avatar} alt="" />
      )}
      <Mark />
      <blockquote className="ag-quote-body">{body}</blockquote>
      <By author={author} date={date} />
    </figure>
  )
}

/** The ghost. One drawing, shipped as an outline, the same at every weight. */
function Mark() {
  return (
    <svg
      className="ag-quote-mark"
      viewBox={`0 0 ${MARK_BOX.w} ${MARK_BOX.h}`}
      aria-hidden="true"
    >
      <path d={MARK_PATH} />
    </svg>
  )
}

/** ONE LINE: the name, then the date, then — where the weight has room for it — the
 *  source. The name is a NAME and stays in the page's own colour: colouring it makes the
 *  accent mean "person", which it means nowhere else, and pulls the eye off the
 *  sentence. */
function By({
  author,
  date,
  source,
  face = false,
}: Pick<QuoteData, "author" | "date" | "source"> & { face?: boolean }) {
  if (!author && !date && !source) return null
  return (
    <figcaption className="ag-quote-by">
      {face && author?.avatar && (
        // biome-ignore lint/performance/noImgElement: an item cannot assume next/image
        <img
          className="ag-quote-face"
          src={author.avatar}
          alt=""
          width={40}
          height={40}
        />
      )}
      {author &&
        (author.href ? (
          <cite>
            <a href={author.href}>{author.name}</a>
          </cite>
        ) : (
          <cite>{author.name}</cite>
        ))}
      {date && <span className="ag-quote-date">{date}</span>}
      {source && (
        <a
          className="ag-quote-source"
          href={source}
          target="_blank"
          rel="noopener noreferrer"
        >
          source ↗
        </a>
      )}
    </figcaption>
  )
}

/* Three weights of one quotation. `prose` is a quotation inside an article at the
   page's own type; `feature` is a quote's own page opening on its words; `card` is THE
   CARD, the same composition the social preview draws. Every number in the card and the
   feature arrives as a custom property computed from the constants in `lib/quote-card`
   — nothing there is a value anybody typed twice. Prose is the one weight that belongs
   to the page rather than to the module, so its few sizes are the page's units. */

.ag-quote {
  margin: 0;
  position: relative;
}

/* THE MARK IS THE SIGNAL AT EVERY WEIGHT, and a rule down the side is not. A rule is
   what every blockquote on the web does; the mark is what makes this one the same
   object as its card, and a reader who has seen the card recognises it. */
.ag-quote-mark {
  position: absolute;
  fill: var(--ag-quote-ink);
}

/* ── prose ──────────────────────────────────────────────────────────────────── */

/* ONE STEP UP FROM THE PAGE. An embed is a thing quoted INTO the article, and a surface
   is what says so: the same words flat on the page read as the author's own. The step
   is a mix off the foreground rather than a theme token, so it is one step up on any
   ground — light, dark, tinted — without a variable to wire. */
.ag-quote-prose {
  padding: 1rem 1.25rem 1rem 1.75rem;
  border-radius: 0.75rem;
  background: color-mix(in oklch, var(--foreground) 4%, transparent);
}
/* THE SAME GHOST AS THE OTHER TWO WEIGHTS, at this scale: faint, barely softened, and
   the first line runs OVER it rather than starting after it. Set beside the words at a
   third of an opacity it was a drop-cap glyph — a fourth voice on a card that has three
   — and the overlap that makes the card and the feature read as one object was gone. */
/* SIZED TO THE FIRST LINE, not to a block. At two and a half lines tall it was right
   behind a paragraph and enormous behind a single sentence, where it ran past the words
   into the attribution and broke the scale. A prose quote is often one line; the mark
   is one line too, and behind a longer one it is a ghost under the opening words rather
   than a shape the whole block sits on. */
.ag-quote-prose .ag-quote-mark {
  left: 0.75rem;
  top: 0.9rem;
  height: 1.6em;
  opacity: 0.14;
  filter: blur(0.6px);
}
/* The words are a QUOTATION and take a serif, the same slot the still fills with its
   `fontFamily`. Set --font-serif on the page to name the face; the fallback is what
   every machine already has. */
.ag-quote-body {
  margin: 0;
  font-family: var(--font-serif, Georgia, "Times New Roman", Times, serif);
  color: color-mix(in oklch, var(--foreground) 92%, transparent);
}
.ag-quote-body > p {
  margin: 0;
}
.ag-quote-body > p + p {
  margin-block-start: 0.5rem;
}

.ag-quote-by {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-block-start: 0.75rem;
  font-size: var(--text-xs, 0.75rem);
  font-style: normal;
  color: var(--muted-foreground);
}
.ag-quote-face {
  flex: none;
  width: 1.5rem;
  height: 1.5rem;
  object-fit: cover;
  border-radius: 9999px;
}
/* The name is a NAME. Colouring it makes the accent mean "person", which it does not
   mean anywhere else, and it pulls the eye off the sentence. */
.ag-quote-by cite {
  font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif);
  font-style: normal;
  color: color-mix(in oklch, var(--foreground) 75%, transparent);
}
.ag-quote-by a {
  color: inherit;
  text-decoration: none;
}
.ag-quote-by a:hover {
  text-decoration: underline;
}
/* THREE VOICES: the words are a quotation, the name is a person, the date is metadata.
   The still draws the same three, and a card disagreeing with its own link preview
   about which is which is the drift the shared module exists to prevent. */
.ag-quote-date,
.ag-quote-source {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: var(--text-xs, 0.75rem);
  color: color-mix(in oklch, var(--muted-foreground) 80%, transparent);
}
.ag-quote-source {
  margin-inline-start: auto;
}

/* ── feature ────────────────────────────────────────────────────────────────── */

/* The page's own weight: what a quote's page opens with. No portrait and no tinted
   ground, but the same STEP prose stands on, the same mark, the same measure ladder and
   the same indent as the card — recognisably the card's words set free of the frame.
   Bare, it was a wall of type with nothing to say where the quotation began and ended;
   the step is the hierarchy. A container, so the mark and the type scale with the column
   it is actually in. */
.ag-quote-feature {
  container-type: inline-size;
  padding: 1.5rem 2rem 1.5rem calc(var(--ag-quote-indent) + 2rem);
  border-radius: 0.75rem;
  background: color-mix(in oklch, var(--foreground) 4%, transparent);
}
/* THE MARK SCALES WITH THE WEIGHT. At the card's size it is a ghost in the picture's
   colour and belongs to the picture; here there is no picture, so at that size and blur
   it is a smear behind the first line. Half the height, a quarter of the blur, a shade
   fainter: a mark that says "quotation" and then gets out of the way of the words. */
.ag-quote-feature .ag-quote-mark {
  left: 2rem;
  top: 1.5rem;
  height: calc(var(--ag-quote-mark) * 0.5);
  opacity: calc(var(--ag-quote-mark-fill) * 0.8);
  filter: blur(calc(var(--ag-quote-soften) * 0.25));
}
/* THE WORDS CLIMB INTO THE MARK. There is no band to centre them in, so they start half
   way down it: the overlap is what gives the composition depth on the card, and hanging
   them below the mark instead is what reads as two objects stacked. */
.ag-quote-feature .ag-quote-body {
  padding-block-start: calc(var(--ag-quote-mark) * 0.25);
  font-size: var(--ag-quote-size);
  line-height: var(--ag-quote-line);
}
/* THE MEASURE IS THE RULE, in real `ch`. */
.ag-quote-feature .ag-quote-body > p {
  max-width: var(--ag-quote-measure);
  text-wrap: pretty;
}
.ag-quote-feature .ag-quote-by {
  margin-block-start: var(--ag-quote-gap);
  gap: 0.75rem;
  font-size: var(--text-sm, 0.875rem);
}
.ag-quote-feature .ag-quote-face {
  width: 2.5rem;
  height: 2.5rem;
}

/* ── the card ───────────────────────────────────────────────────────────────── */

/* A container, so every distance inside can be a share of the CARD rather than of the
   page. That is what lets one set of constants drive a 1200px preview and a 480px
   column without a breakpoint anywhere. */
.ag-quote-card {
  container-type: inline-size;
  position: relative;
  aspect-ratio: var(--ag-quote-aspect);
  overflow: hidden;
  background: var(--ag-quote-ground);
  border-radius: 0.5rem;
  color: var(--foreground);
}

/* THE BACKGROUND IS TWO THINGS AND ONLY TWO: a flat tinted ground and the picture, with
   a dissolve between them. The picture is a square as tall as the frame, never cropped
   sideways — it is SLID so its subject clears the fade, and the mask is what hides the
   rest. Anchoring it instead means the fade always eats whoever stands on that side. */
/* SIZED IN cqw ON BOTH AXES, no percentage height and no aspect-ratio. A replaced
   element with `height: 100%` inside a box whose own height comes from `aspect-ratio`
   is a case Safari resolves as indefinite: the image collapsed to a strip along the top
   edge while Chrome drew it full height. A square whose side is stated outright is the
   same number in every engine. */
.ag-quote-bleed {
  position: absolute;
  top: 0;
  left: var(--ag-quote-slot);
  width: var(--ag-quote-square);
  height: var(--ag-quote-square);
  max-width: none;
  object-fit: cover;
  mask-image: var(--ag-quote-dissolve);
  -webkit-mask-image: var(--ag-quote-dissolve);
}

/* The ghost, in the picture's own colour so it belongs to the photograph rather than to
   the type. It takes no space: the words are composed over it, and at this opacity they
   pass straight across. */
.ag-quote-mark {
  position: absolute;
  left: var(--ag-quote-margin);
  top: var(--ag-quote-edge);
  height: var(--ag-quote-mark);
  width: auto;
  fill: var(--ag-quote-ink);
  opacity: var(--ag-quote-mark-fill);
  filter: blur(var(--ag-quote-soften));
}

/* The words are CENTRED in the band the mark and the attribution leave, so the air
   around them never depends on how long the quote is. */
.ag-quote-card .ag-quote-body {
  position: absolute;
  left: var(--ag-quote-indent);
  top: var(--ag-quote-edge);
  /* The band's floor is the attribution's CAP, not its baseline: the still reserves
     (CAP+DESC)·nameSize below the band and the block is centred against that. */
  bottom: var(--ag-quote-floor);
  /* The column IS --ag-quote-column: quoteSet was fed exactly this width, so any
     arithmetic on top of it here re-wraps the lines the size was chosen for. */
  width: var(--ag-quote-column);
  display: flex;
  flex-direction: column;
  justify-content: center;
  font-size: var(--ag-quote-size);
  line-height: var(--ag-quote-line);
  color: var(--foreground);
}
/* THE MEASURE IS THE RULE, and here it is in real `ch` — the browser knows exactly how
   wide a character of this face is and the still can only estimate. Both carry the same
   number of characters a line; only the still guesses where a word lands. */
.ag-quote-card .ag-quote-body > p {
  max-width: var(--ag-quote-measure);
  text-wrap: pretty;
}

/* ONE LINE: the name, then the date after it. Stacked they read as two facts of equal
   weight and take twice the room at the foot of a frame that has none to spare. It sits
   as far off the floor as the mark hangs from the ceiling — a matched pair holding the
   frame — and its size comes off the FRAME, never off the quote, so a set of cards has
   one caption rather than a caption that resizes for reasons nobody can see. */
.ag-quote-card .ag-quote-by {
  position: absolute;
  left: var(--ag-quote-margin);
  bottom: var(--ag-quote-edge);
  margin: 0;
  gap: calc(var(--ag-quote-name) * 1.6);
  font-size: var(--ag-quote-name);
}
.ag-quote-card .ag-quote-by cite {
  font-size: inherit;
  color: color-mix(in oklch, var(--foreground) 75%, transparent);
}
.ag-quote-card .ag-quote-date {
  font-size: var(--ag-quote-date);
}
